from typing import Protocol, runtime_checkable

@runtime_checkable
class Speaker(Protocol):
    def speak(self) -> str: ...

class Robot:
    def speak(self) -> str:
        return "бип"

print(isinstance(Robot(), Speaker), isinstance("hi", Speaker))

